package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.util.GroupMatcher;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class TripleIndexBindingShapeTest {

	private static final long[] PATTERN_VALUES = { 11L, 22L, 33L, 0L };

	private final List<TripleIndex> createdIndexes = new ArrayList<>();
	private TripleStore tripleStore;
	private File dataDir;

	@BeforeEach
	void setUp(@TempDir File dataDir) throws Exception {
		this.dataDir = dataDir;
		tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
	}

	@AfterEach
	void tearDown() throws Exception {
		for (TripleIndex index : createdIndexes) {
			index.close();
		}
		if (tripleStore != null) {
			tripleStore.close();
		}
		LmdbTestUtil.deleteDir(dataDir);
	}

	@Test
	void precomputesEveryBindingShapeForEveryIndexOrder() throws Exception {
		tripleStore.startTransaction();
		for (String fieldSequence : permutations("spoc")) {
			TripleIndex index = new TripleIndex("shape-" + fieldSequence, fieldSequence, false,
					tripleStore.env, tripleStore.writeTxn);
			createdIndexes.add(index);
			for (int bindingMask = 0; bindingMask < TripleIndex.BINDING_SHAPE_COUNT; bindingMask++) {
				assertShape(index, fieldSequence, bindingMask);
			}
		}
		tripleStore.endTransaction(true);
	}

	@Test
	void preselectsPrimaryAndSecondaryIndexesForEveryBindingShape() {
		List<String> configuredIndexes = List.of("spoc", "posc");
		for (int bindingMask = 0; bindingMask < TripleIndex.BINDING_SHAPE_COUNT; bindingMask++) {
			String expectedPrimary = expectedPrimary(configuredIndexes, bindingMask);
			assertEquals(expectedPrimary,
					new String(tripleStore.getBestPageEstimatorIndex(bindingMask).getFieldSeq()));
			TripleIndex secondary = tripleStore.getSecondaryNoPrefixEstimatorIndex(bindingMask);
			String actualSecondary = secondary == null ? null : new String(secondary.getFieldSeq());
			assertEquals(expectedSecondary(configuredIndexes, expectedPrimary, bindingMask), actualSecondary);
		}
	}

	private String expectedPrimary(List<String> indexes, int bindingMask) {
		String best = null;
		int bestPrefix = -1;
		int bestLayoutScore = Integer.MIN_VALUE;
		for (String candidate : indexes) {
			int prefix = expectedPrefixLength(candidate, bindingMask);
			int layoutScore = expectedLayoutScore(candidate, bindingMask);
			if (prefix > bestPrefix || prefix == bestPrefix && layoutScore > bestLayoutScore) {
				best = candidate;
				bestPrefix = prefix;
				bestLayoutScore = layoutScore;
			}
		}
		return best;
	}

	private String expectedSecondary(List<String> indexes, String primary, int bindingMask) {
		if (bindingMask == 0 || expectedPrefixLength(primary, bindingMask) != 0) {
			return null;
		}

		String best = null;
		boolean bestHasDifferentLeadingField = false;
		int bestScore = Integer.MIN_VALUE;
		for (String candidate : indexes) {
			if (candidate.equals(primary) || expectedPrefixLength(candidate, bindingMask) != 0) {
				continue;
			}
			boolean differentLeadingField = candidate.charAt(0) != primary.charAt(0);
			int score = expectedLayoutScore(candidate, bindingMask);
			if (best == null || differentLeadingField && !bestHasDifferentLeadingField
					|| differentLeadingField == bestHasDifferentLeadingField && score > bestScore) {
				best = candidate;
				bestHasDifferentLeadingField = differentLeadingField;
				bestScore = score;
			}
		}
		return best;
	}

	private void assertShape(TripleIndex index, String fieldSequence, int bindingMask) {
		int expectedPrefixLength = expectedPrefixLength(fieldSequence, bindingMask);
		int expectedMatcherMask = expectedMatcherMask(fieldSequence, bindingMask);
		int expectedPrefixFieldMask = expectedPrefixFieldMask(fieldSequence, expectedPrefixLength);
		int expectedResidualMask = expectedMatcherMask & ~((1 << expectedPrefixLength) - 1);

		assertEquals(expectedPrefixLength, index.getPatternScore(bindingMask));
		assertEquals(expectedMatcherMask, index.getMatcherMask(bindingMask));
		assertEquals(expectedPrefixFieldMask, index.getPrefixFieldMask(bindingMask));
		assertEquals(expectedResidualMask, index.getResidualMatcherMask(bindingMask));
		assertEquals(expectedLayoutScore(fieldSequence, bindingMask), index.getResidualLayoutScore(bindingMask));
		assertEquals(bindingMask, TripleIndex.bindingMask(
				valueForMask(bindingMask, TripleIndex.SUBJ_IDX),
				valueForMask(bindingMask, TripleIndex.PRED_IDX),
				valueForMask(bindingMask, TripleIndex.OBJ_IDX),
				valueForMask(bindingMask, TripleIndex.CONTEXT_IDX)));

		assertRange(index, bindingMask, expectedPrefixFieldMask, false);
		assertRange(index, bindingMask, expectedPrefixFieldMask, true);
		assertResidualMatcher(index, fieldSequence, bindingMask, expectedPrefixLength, expectedResidualMask);
	}

	private void assertRange(TripleIndex index, int bindingMask, int prefixFieldMask, boolean upper) {
		ByteBuffer key = ByteBuffer.allocate(TripleIndex.MAX_KEY_LENGTH);
		if (upper) {
			index.getMaxKeyForPattern(key, PATTERN_VALUES[0], PATTERN_VALUES[1], PATTERN_VALUES[2],
					PATTERN_VALUES[3], bindingMask);
		} else {
			index.getMinKeyForPattern(key, PATTERN_VALUES[0], PATTERN_VALUES[1], PATTERN_VALUES[2],
					PATTERN_VALUES[3], bindingMask);
		}
		key.flip();
		long[] actual = new long[4];
		index.keyToQuad(key, actual);

		long fill = upper ? Long.MAX_VALUE : 0L;
		long[] expected = new long[4];
		for (int field = 0; field < expected.length; field++) {
			expected[field] = (prefixFieldMask & (1 << field)) != 0 ? PATTERN_VALUES[field] : fill;
		}
		assertArrayEquals(expected, actual);
	}

	private void assertResidualMatcher(TripleIndex index, String fieldSequence, int bindingMask,
			int prefixLength, int residualMask) {
		long[] pattern = patternForMask(bindingMask);
		GroupMatcher matcher = index.createResidualMatcher(pattern[0], pattern[1], pattern[2], pattern[3], bindingMask);
		if (residualMask == 0) {
			assertNull(matcher);
			return;
		}

		assertNotNull(matcher);
		long[] candidate = PATTERN_VALUES.clone();
		for (int position = 0; position < prefixLength; position++) {
			candidate[fieldIndex(fieldSequence.charAt(position))] += 100L;
		}
		assertTrue(matcher.matches(encoded(index, candidate)));

		int residualPosition = Integer.numberOfTrailingZeros(residualMask);
		candidate[fieldIndex(fieldSequence.charAt(residualPosition))] += 1L;
		assertFalse(matcher.matches(encoded(index, candidate)));
	}

	private ByteBuffer encoded(TripleIndex index, long[] values) {
		ByteBuffer key = ByteBuffer.allocate(TripleIndex.MAX_KEY_LENGTH);
		index.toKey(key, values[0], values[1], values[2], values[3]);
		return key.flip();
	}

	private static long[] patternForMask(int bindingMask) {
		long[] pattern = new long[4];
		for (int field = 0; field < pattern.length; field++) {
			pattern[field] = (bindingMask & (1 << field)) != 0 ? PATTERN_VALUES[field] : -1L;
		}
		return pattern;
	}

	private static long valueForMask(int bindingMask, int field) {
		return (bindingMask & (1 << field)) != 0 ? PATTERN_VALUES[field] : -1L;
	}

	private static int expectedPrefixLength(String fieldSequence, int bindingMask) {
		int prefixLength = 0;
		while (prefixLength < fieldSequence.length()
				&& (bindingMask & (1 << fieldIndex(fieldSequence.charAt(prefixLength)))) != 0) {
			prefixLength++;
		}
		return prefixLength;
	}

	private static int expectedMatcherMask(String fieldSequence, int bindingMask) {
		int matcherMask = 0;
		for (int position = 0; position < fieldSequence.length(); position++) {
			if ((bindingMask & (1 << fieldIndex(fieldSequence.charAt(position)))) != 0) {
				matcherMask |= 1 << position;
			}
		}
		return matcherMask;
	}

	private static int expectedPrefixFieldMask(String fieldSequence, int prefixLength) {
		int prefixFieldMask = 0;
		for (int position = 0; position < prefixLength; position++) {
			prefixFieldMask |= 1 << fieldIndex(fieldSequence.charAt(position));
		}
		return prefixFieldMask;
	}

	private static int expectedLayoutScore(String fieldSequence, int bindingMask) {
		int score = 0;
		for (int position = 0; position < fieldSequence.length(); position++) {
			if ((bindingMask & (1 << fieldIndex(fieldSequence.charAt(position)))) != 0) {
				score += 1 << ((fieldSequence.length() - position - 1) * 4);
			}
		}
		return score;
	}

	private static int fieldIndex(char field) {
		return switch (field) {
		case 's' -> TripleIndex.SUBJ_IDX;
		case 'p' -> TripleIndex.PRED_IDX;
		case 'o' -> TripleIndex.OBJ_IDX;
		case 'c' -> TripleIndex.CONTEXT_IDX;
		default -> throw new IllegalArgumentException("Invalid field: " + field);
		};
	}

	private static List<String> permutations(String fields) {
		List<String> permutations = new ArrayList<>();
		appendPermutations("", fields, permutations);
		return permutations;
	}

	private static void appendPermutations(String prefix, String remaining, List<String> permutations) {
		if (remaining.isEmpty()) {
			permutations.add(prefix);
			return;
		}
		for (int i = 0; i < remaining.length(); i++) {
			appendPermutations(prefix + remaining.charAt(i),
					remaining.substring(0, i) + remaining.substring(i + 1), permutations);
		}
	}
}
